// Des: Command-line parsing for scra
// Flo: walk argv > flags with values > switches > first word = command, second = URL > typed BadUsage on anything unknown
// I/O: argv strings (caller) > Args struct (slices into argv)
// ===================================================================
const std = @import("std");
const CF = .{ .vals = [_][2][]const u8{ .{ "--conf", "conf" }, .{ "--format", "fmtz" }, .{ "--out", "outz" }, .{ "--seed-file", "seed" }, .{ "--sitemap", "smap" }, .{ "--add", "adds" }, .{ "--click", "clic" }, .{ "--steps", "ste2" }, .{ "--account", "acct" }, .{ "--spec", "spec" }, .{ "--list", "list" }, .{ "--selector", "sele" }, .{ "--stream", "strm" } }, .nums = [_][2][]const u8{ .{ "--decl", "decl" }, .{ "--wait", "wait" }, .{ "--scroll", "scrl" }, .{ "--follow", "foll" } } };
pub const Args = struct { cmdz: []const u8 = "", urlz: []const u8 = "", json: bool = false, live: bool = false, forc: bool = false, onzz: bool = false, offz: bool = false, conf: []const u8 = "", fmtz: []const u8 = "jsonl", outz: []const u8 = "", seed: []const u8 = "", smap: []const u8 = "", adds: []const u8 = "", decl: u32 = 0, foll: u32 = 0, helz: bool = false, chek: bool = false, geoz: []const u8 = "", wait: u32 = 0, scrl: u32 = 0, clic: []const u8 = "", cons: bool = false, ste2: []const u8 = "", acct: []const u8 = "", spec: []const u8 = "", parm: []const u8 = "", strm: []const u8 = "", list: []const u8 = "", sele: []const u8 = "" };
fn geozOkay(tex2: []const u8) bool { return tex2.len == 2 and std.ascii.isAlphabetic(tex2[0]) and std.ascii.isAlphabetic(tex2[1]); }
pub fn argsRead(argv: []const []const u8, allo: std.mem.Allocator) !Args { var args: Args = .{}; var indx: usize = 0; while (indx < argv.len) : (indx += 1) { const item = argv[indx]; if (std.mem.eql(u8, item, "--json")) { args.json = true; continue; } if (std.mem.eql(u8, item, "--live")) { args.live = true; continue; } if (std.mem.eql(u8, item, "--force")) { args.forc = true; continue; } if (std.mem.eql(u8, item, "--on")) { args.onzz = true; continue; } if (std.mem.eql(u8, item, "--off")) { args.offz = true; continue; } if (std.mem.eql(u8, item, "--consent")) { args.cons = true; continue; } if (std.mem.eql(u8, item, "--check")) { args.chek = true; continue; } if (std.mem.eql(u8, item, "--help") or std.mem.eql(u8, item, "-h")) { args.helz = true; continue; }
var done = false; inline for (CF.vals) |pair| { if (!done and std.mem.eql(u8, item, pair[0])) { indx += 1; if (indx >= argv.len) return error.BadUsage; @field(args, pair[1]) = argv[indx]; done = true; } } inline for (CF.nums) |pair| { if (!done and std.mem.eql(u8, item, pair[0])) { indx += 1; if (indx >= argv.len) return error.BadUsage; @field(args, pair[1]) = std.fmt.parseInt(u32, argv[indx], 10) catch return error.BadUsage; done = true; } } if (done) continue;
if (std.mem.eql(u8, item, "--geoz")) { indx += 1; if (indx >= argv.len or !geozOkay(argv[indx])) return error.BadUsage; args.geoz = argv[indx]; continue; } if (std.mem.eql(u8, item, "--param")) { indx += 1; if (indx >= argv.len or std.mem.indexOfScalar(u8, argv[indx], '=') == null) return error.BadUsage; args.parm = if (args.parm.len == 0) argv[indx] else try std.fmt.allocPrint(allo, "{s}&{s}", .{ args.parm, argv[indx] }); continue; } if (item.len > 0 and item[0] == '-') return error.BadUsage; if (args.cmdz.len == 0) { args.cmdz = item; } else if (args.urlz.len == 0) { args.urlz = item; } else return error.BadUsage; } if (args.onzz and args.offz) return error.BadUsage; if (args.forc and !args.live) return error.BadUsage; return args; }
